const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location - Pedrógão Grande, Portugal
  const pedrogao = ee.Geometry.Point([-8.1458, 39.9833]);
  const region = pedrogao.buffer(20000); // 20km buffer to cover the fire area

  // 2. Define time period
  const startDate = '2017-06-16';
  const endDate = '2017-06-21';

  // 3. Load MODIS fire product (Terra)
  let fireCol = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const colSize = fireCol.size().getInfo();
  console.log(`MODIS Fire Images Found: ${colSize}`);

  if (colSize === 0) {
    // Try FIRMS MODIS data as fallback
    fireCol = ee.ImageCollection('FIRMS')
      .filterDate(startDate, endDate)
      .filterBounds(region);

    const firmsSize = fireCol.size().getInfo();
    console.log(`FIRMS Images Found: ${firmsSize}`);

    if (firmsSize === 0) {
      console.log("No fire detection data available for this period.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 4. Process fire detection - use FireMask band
  const fireMosaic = fireCol.select('FireMask').max();

  // 5. Count fire pixels (FireMask > 7 indicates fire with varying confidence)
  const fireStats = fireMosaic.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.sum(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = fireStats.FireMask_count || 0;
  const fireSum = fireStats.FireMask_sum || 0;

  console.log(`Total Pixels Analyzed: ${pixelCount}`);
  console.log(`Fire Pixels Sum: ${fireSum}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (fireSum === null || fireSum === undefined) {
    console.log("Fire calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Determine answer
  // FireMask values: 7-9 indicate fire detections
  const fireDetected = fireSum > 0;

  console.log(`Fire Detection Result: ${fireDetected ? 'FIRES DETECTED' : 'No fires detected'}`);

  if (fireDetected) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
